  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    node_map = {}
    for node in nodes:
        node_map[node['id']] = node
    children = {node['id']: [] for node in nodes}
    for node in nodes:
        parent_id = node['parent']
        if parent_id is not None:
            children[parent_id].append(node['id'])
    # sort nodes by depth descending, then id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed = set()
    removed_order = []
    def required_symbols_present(except_id):
        for sym in required_symbols:
            found = False
            for node in nodes:
                if node['id'] != except_id and node['id'] not in removed and node['symbol'] == sym:
                    found = True
                    break
            if not found:
                return False
        return True
    for node in sorted_nodes:
        nid = node['id']
        if not node['removable']:
            continue
        if nid == 'root' or node['depth'] == 0:
            continue
        # check no retained children
        if any(cid not in removed for cid in children[nid]):
            continue
        # check required symbols still present after tentative removal
        if not required_symbols_present(nid):
            continue
        removed.add(nid)
        removed_order.append(nid)
    retained = [n['id'] for n in nodes if n['id'] not in removed]
    retained.sort()
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained
    }"
}
